body {
  background-color: #f5f6f8;
  color: #18181b;
  font-family: system-ui, "Segoe UI", sans-serif;
  line-height: 1.6;
  padding: 16px;
}

h1 { font-size: 26px; }

h2 {
  font-size: 15px;
  font-family: ui-monospace, "Cascadia Mono", monospace;
  margin: 0 0 8px;
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.call {
  background-color: #ffffff;
  padding: 16px;
  border-radius: 10px;
  margin-bottom: 12px;
  border-left: 4px solid #e4e4e7;
}

.call.ok { border-left-color: #0a7a35; }
.call.bad { border-left-color: #b91c1c; }

.status {
  display: inline-block;
  min-width: 40px;
  text-align: center;
  border-radius: 999px;
  padding: 1px 8px;
  font-size: 13px;
  font-weight: 700;
  color: #ffffff;
  background-color: #71717a;
}

.s-2xx { background-color: #0a7a35; }
.s-4xx { background-color: #b45309; }
.s-5xx { background-color: #b91c1c; }
.s-err { background-color: #b91c1c; }

pre {
  background-color: #f4f4f5;
  border-radius: 8px;
  padding: 10px 12px;
  margin: 0 0 8px;
  overflow-x: auto;
  font-size: 13px;
  white-space: pre-wrap;
}

pre:last-child { margin-bottom: 0; }

// GitHub Actions workflow-ийг объект хэлбэрээр буцаа.
// on: хэзээ ажиллах (жишээ нь ["push", "pull_request"]).
// jobs: ажлууд. Дараалал нь needs-ээр тодорхойлогдоно:
//   test → build → deploy (build нь test-ийг, deploy нь build-ыг шаардана).

function buildWorkflow() {
  // энд бичнэ үү
}

// «Workflow турших самбар». Энэ файлыг өөрчлөх шаардлагагүй.
const output = document.getElementById("output");
function panel(cls, testid, title, lines) {
  const box = document.createElement("section");
  box.className = "call " + cls;
  box.dataset.testid = testid;
  const h = document.createElement("h2");
  h.textContent = title;
  box.append(h);
  for (const line of lines) {
    const p = document.createElement("pre");
    p.textContent = line;
    box.append(p);
  }
  output.append(box);
  return box;
}

window.WF = null;

try {
  window.WF = buildWorkflow();
  panel("ok", "wf", "Workflow бүтэц", [JSON.stringify(window.WF, null, 2)]);
} catch (problem) {
  panel("bad", "error", "Алдаа", [problem.message]);
}

document.body.dataset.ready = "1";

