// CI workflow: test → build → deploy (needs-ээр холбогдсон).

function buildWorkflow() {
  return {
    name: "CI",
    on: ["push", "pull_request"],
    jobs: {
      test: { steps: ["install", "test"] },
      build: { needs: ["test"], steps: ["build"] },
      deploy: { needs: ["build"], steps: ["deploy"], if: "branch == 'main'" },
    },
  };
}
